python3 - <<'PY'
import re,glob,os
for f in sorted(glob.glob('compositions/*.html')):
    s=open(f).read()
    ids=set(re.findall(r'id="([^"]+)"',s))
    sels=set(re.findall(r'"([^"]+)"',s))
    missing=[]
    for sel in sels:
        if sel.startswith('#'):
            parts=re.split(r'[ ,>]+',sel)
            for p in parts:
                p=p.strip()
                if p.startswith('#') and ':' not in p:
                    id_=p[1:]
                    if id_ not in ids:
                        # may be prefix with space descendant
                        missing.append(p)
    if missing:
        print(f, sorted(set(missing)))
PY

